local function getConns(sig)
    if not (sig and getconnections) then return {} end
    local ok, list = pcall(getconnections, sig)
    return ok and type(list) == "table" and list or {}
end
local function setConns(sig, enabled, mine)
    for _, c in ipairs(getConns(sig)) do
        local f = nil
        pcall(function() f = c.Function end)
        if not (OURFN[f] or (mine and f == mine)) then
            pcall(function() if enabled then c:Enable() else c:Disable() end end)
        end
    end
end
