local function queues()
    local f = Workspace:FindFirstChild("LobbyQueues"); local out = {}
    if f then
        for _, q in ipairs(f:GetChildren()) do
            local t = q:FindFirstChild("TouchPart")
            if t and t:IsA("BasePart") then out[#out + 1] = t end
        end
    end
    table.sort(out, function(a, b) return a.Parent.Name < b.Parent.Name end)
    return out
end
local function inQueue() return S.lobby and S.lobby.inQueue == true end
local function joinQueue()
    if inQueue() and S.lobby.isHost then return true end
    for _, t in ipairs(queues()) do
        local root = hrp(); if not root then return false end
        streamAround(t.Position)
        root = hrp(); if not root then return false end
        root.CFrame = t.CFrame
        touch(t)
        local t0 = os.clock()
        while os.clock() - t0 < 4 and not inQueue() do task.wait(0.1) end
        if inQueue() then
            if S.lobby.isHost then return true end
            fire("LobbyQueueRemotes.LeaveQueue", tostring(S.lobby.queueId))
            task.wait(1.2)
        end
    end
    return inQueue() and S.lobby.isHost == true
end
local function createRun()
    if S.lobbyBusy then return end
    S.lobbyBusy = true
    local want = tonumber(tostring(val("lb_part", "Part 1")):match("%d")) or 1
    if not joinQueue() then
        S.lobbyBusy = false
        notify(L["No free queue"])
        return
    end
    local q = tostring(S.lobby.queueId)
    local before = S.lobbyAt
    fire("LobbyQueueRemotes.SelectMaxPlayers", q, math.floor(tonumber(val("lb_max", 1)) or 1), on("lb_friends") == true, want)
    local t0 = os.clock()
    while os.clock() - t0 < 4 and S.lobbyAt == before do task.wait(0.1) end
