local function saveOnce(key, get)
    if S.saved[key] == nil then
        local ok, v = pcall(get)
        if ok then S.saved[key] = { v = v } end
    end
end
local function restore(key, set)
    local s = S.saved[key]
    if s then pcall(set, s.v); S.saved[key] = nil end
end
