local function pickupTick()
    if not on("pk_auto") or S.storyBusy then return end
    local cats = msel("pk_cats"); if not cats then return end
    local root = hrp(); if not root then return end
    local range = tonumber(val("pk_range", 0)) or 0
    local best, bd
    for _, it in ipairs(itemsOf(cats)) do
        if it.c ~= "Guides" and it.c ~= "Delivery Spots" and it.c ~= "Quest Items" then
            local until_ = S.tried[it.o]
            if not until_ or os.clock() > until_ then
                local part = mainPart(it.o)
                if part then
                    local d = (part.Position - root.Position).Magnitude
                    if (range <= 0 or d <= range) and (not bd or d < bd) then best, bd = it.o, d end
                end
            end
        end
    end
    if best then
        S.tried[best] = os.clock() + 12
        interact(best)
    end
