local function recordSafe()
    local root, h = hrp(), hum()
    if not (root and h) or os.clock() - S.lastSafeRec < 1 then return end
    S.lastSafeRec = os.clock()
    if h.FloorMaterial == Enum.Material.Air then return end
    local _, d = nearestThreat(root.Position)
    if d and d < 120 then return end
    local last = S.safe[#S.safe]
    if last and (last - root.Position).Magnitude < 15 then return end
    S.safe[#S.safe + 1] = root.Position
    if #S.safe > 50 then table.remove(S.safe, 1) end
end
local function evadeTo(m)
    local root, mp = hrp(), mPos(m)
    if not (root and mp) then return end
    local best, bd
    for _, p in ipairs(S.safe) do
        if (p - mp).Magnitude >= 100 then
            local d = (p - root.Position).Magnitude
            if not bd or d < bd then best, bd = p, d end
        end
    end
    if not best then
        local away = root.Position - mp
        away = Vector3.new(away.X, 0, away.Z)
        if away.Magnitude < 0.1 then away = Vector3.new(1, 0, 0) end
        local guess = root.Position + away.Unit * 90
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = { lp.Character, m }
        local hit = Workspace:Raycast(guess + Vector3.new(0, 60, 0), Vector3.new(0, -200, 0), params)
        if not hit or hit.Position.Y > root.Position.Y + 15 then return end
        best = hit.Position
    end
    root.AssemblyLinearVelocity = Vector3.zero
    root.CFrame = CFrame.new(best + Vector3.new(0, 3, 0))
    S.evades = S.evades + 1
    S.lastEvade = os.clock()
end
local function evadeTick()
    if not on("ev_on") or not alive() or S.guardPause then return end
    if os.clock() - S.lastEvade < 1.2 then return end
    local m, d = nearestThreat()
    if not m then return end
    local h = m:FindFirstChildOfClass("Humanoid")
    if h and h.WalkSpeed == 0 then return end
    local lim = tonumber(val("ev_dist", 30)) or 30
    if d <= lim or (on("ev_hunt") and hunting(m) and d <= lim * 2.5) then evadeTo(m) end
end
