local TAGS = {}
local function tag(key, adornee, text, color, hlTarget)
    local t = TAGS[key]
    if not t then
        local bb = Instance.new("BillboardGui")
        bb.Size = UDim2.fromOffset(170, 30); bb.AlwaysOnTop = true; bb.StudsOffset = Vector3.new(0, 2.5, 0); bb.LightInfluence = 0
        bb.MaxDistance = math.huge
        local tl = Instance.new("TextLabel")
        tl.BackgroundTransparency = 1; tl.Size = UDim2.fromScale(1, 1); tl.Font = Enum.Font.GothamBold
        tl.TextSize = 13; tl.TextStrokeTransparency = 0.35; tl.Parent = bb
        bb.Parent = ESPF
        t = { bb = bb, tl = tl }
        TAGS[key] = t
    end
    t.seen = true
    if t.bb.Adornee ~= adornee then t.bb.Adornee = adornee end
    t.tl.Text = text
    t.tl.TextColor3 = color
    local ai = Workspace:FindFirstChild("GameAI")
    if hlTarget and hlTarget:IsA("Model") and (hlTarget:FindFirstChildOfClass("Humanoid") or (ai and hlTarget:IsDescendantOf(ai))) then
        t.cham = t.cham or {}
        local anyVisible = false
        for _, p in ipairs(hlTarget:GetDescendants()) do
            if p:IsA("BasePart") and p.Transparency < 0.9 then
                anyVisible = true
                if not t.cham[p] then
                    local a = Instance.new("BoxHandleAdornment")
                    a.Adornee = p; a.Size = p.Size; a.AlwaysOnTop = true; a.ZIndex = 5; a.Transparency = 0.55
                    a.Parent = ESPF
                    t.cham[p] = a
                end
            end
        end
        local root = not anyVisible and (hlTarget:FindFirstChild("HumanoidRootPart") or mainPart(hlTarget))
        if root then
            local ok, cf, size = pcall(function() return hlTarget:GetBoundingBox() end)
            if ok and size.Magnitude < 80 then
                local a = t.cham[root]
                if not a then
                    a = Instance.new("BoxHandleAdornment")
                    a.Adornee = root; a.AlwaysOnTop = true; a.ZIndex = 5; a.Transparency = 0.55
                    a.Parent = ESPF
                    t.cham[root] = a
                end
                a.Size = size
                a.CFrame = root.CFrame:ToObjectSpace(cf)
            end
        end
        for p, a in pairs(t.cham) do
            if not p.Parent then a:Destroy(); t.cham[p] = nil
            else a.Color3 = color; if p ~= root and a.Size ~= p.Size then a.Size = p.Size end end
        end
    elseif hlTarget then
        if not t.hl then
            local h = Instance.new("Highlight")
            h.FillTransparency = 0.65; h.OutlineTransparency = 0; h.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            h.Parent = ESPF
            t.hl = h
        end
        t.hl.Adornee = hlTarget; t.hl.FillColor = color; t.hl.OutlineColor = color
    elseif t.hl then
        t.hl:Destroy(); t.hl = nil
    end
end
local function sweepTags()
    for k, t in pairs(TAGS) do
        if not t.seen then
            pcall(function() t.bb:Destroy() end)
            if t.hl then pcall(function() t.hl:Destroy() end) end
            if t.cham then for _, a in pairs(t.cham) do pcall(function() a:Destroy() end) end end
            TAGS[k] = nil
        else
            t.seen = false
        end
    end
end
