local function espTick()
    local root = hrp()
    local p0 = root and root.Position
    local function dist(pos) return p0 and math.floor((pos - p0).Magnitude) or 0 end
    local nearM, nearD = nil, nil
    for _, m in ipairs(monsters()) do
        local p = mPos(m)
        if p then
            local d = dist(p)
            if not nearD or d < nearD then nearM, nearD = m, d end
            if on("sv_esp") then
                local part = m:FindFirstChild("Head") or m:FindFirstChild("HumanoidRootPart") or mainPart(m)
                if part then
                    local txt = m.Name .. " · " .. d .. "m" .. (hunting(m) and " · HUNTING YOU" or "")
                    tag(m, part, txt, hunting(m) and Color3.fromRGB(255, 40, 40) or Color3.fromRGB(255, 120, 80), m)
                end
            end
        end
    end
    if nearM then
        local s = (S.chase or hunting(nearM)) and "Chasing you" or "Roaming"
        setText(UI.svState, L["Monster · "] .. nearD .. L["m · "] .. s)
    else
        setText(UI.svState, L["Monster · none near"])
    end
    if on("esp_items") then
        local cats = msel("esp_cats")
        local maxD = tonumber(val("esp_max", 0)) or 0
        local shown = {}
        for _, it in ipairs(itemsOf(cats)) do
            local part = mainPart(itemTarget(it.o, it.c))
            if part then
                local d = dist(part.Position)
                if maxD <= 0 or d <= maxD then shown[#shown + 1] = { it = it, part = part, d = d } end
            end
        end
        table.sort(shown, function(a, b) return a.d < b.d end)
        for i = 1, math.min(#shown, 80) do
            local s = shown[i]
            tag(s.it.o, s.part, itemLabel(s.it.o, s.it.c) .. " · " .. s.d .. "m", CAT_COLOR[s.it.c] or Color3.new(1, 1, 1))
        end
        setText(UI.espCount, L["Showing "] .. math.min(#shown, 80) .. L[" items"])
    else
        setText(UI.espCount, L["Off"])
    end
    if on("esp_players") then
        for _, p in ipairs(Players:GetPlayers()) do
            local c = p.Character
            local head = c and c:FindFirstChild("Head")
            if p ~= lp and head then tag(p, head, p.DisplayName .. " · " .. dist(head.Position) .. "m", Color3.fromRGB(140, 200, 255), c) end
        end
    end
    if on("esp_obj") then
        local dp = missionPos(curMission())
        if dp then tag("__obj", dp, L["Objective · "] .. dist(dp.Position) .. "m", Color3.fromRGB(255, 215, 0)) end
    end
    if on("gd_mark") then
        local g = GUIDE.current()
        local list = (g and g.targets and #g.targets > 0) and g.targets or { g and g.target }
        for i, e in ipairs(list) do
            local t, custom = e, nil
            if type(e) == "table" then t, custom = e.o, e.l end
            local part = typeof(t) == "Instance" and ((t:IsA("BasePart") and t) or (t:IsA("Attachment") and t.Parent:IsA("BasePart") and t.Parent) or mainPart(t))
            if part then
                local nice = custom or t.Name:gsub("^Faucet0*(%d+)", "Tap %1"):gsub("^Drain0*%d*", "Drain")
                local label = (#list > 1 and nice or (custom or ("Next · " .. tostring(g.title)))) .. " · " .. dist(part.Position) .. "m"
                tag("__guide" .. i, part, label, Color3.fromRGB(120, 255, 160), t:IsA("Model") and t or part)
            end
        end
    end
    sweepTags()
end
