section(L["Suggestions"], function()
    local SuggestTab = Window:AddTab(L["Suggestions"], "message-square")
    local DISCORD_INVITE = CONFIG.DISCORD_INVITE
    local FEEDBACK_URL = "https://v0-secure-discord-proxy.vercel.app/api/v2sender"
    local FEEDBACK_VERSION = CONFIG.VERSION
    local _request = request or (syn and syn.request) or http_request
    local function fbTrim(s) return (tostring(s or ""):gsub("^%s*(.-)%s*$", "%1")) end
    local okId, cid = pcall(function() return game:GetService("RbxAnalyticsService"):GetClientId() end)
    local FB_HWID = (okId and type(cid) == "string" and cid ~= "") and cid or tostring(lp.UserId)
    local FB_ERRMAP = {
        empty = L["The message is empty."], no_links = L["Links are not allowed."],
        too_long = "The message is too long (500 characters maximum).",
        rate_limited = "You reached the limit. Try again later.", network = "Network error.",
        no_request = "Your executor cannot send requests.", bad_response = "The server returned an unexpected response.",
        unreachable = "Your executor cannot reach the server. Try a different one.",
    }
    local function sendFeedback(ftype, msg)
        if not _request then return false, "no_request" end
        local ok, res = pcall(function()
            return _request({
                Url = FEEDBACK_URL, Method = "POST",
                Headers = { ["Content-Type"] = "application/json" },
                Body = HttpService:JSONEncode({ type = ftype, message = msg, hwid = FB_HWID, placeId = tostring(game.PlaceId), username = lp.Name, version = FEEDBACK_VERSION }),
            })
        end)
        if not ok or not res then return false, "network" end
        if type(res) == "string" then return false, "unreachable" end
        if type(res) ~= "table" then return false, "network" end
        local code = res.StatusCode or res.status_code or res.Status or res.status
        if type(code) == "number" and code ~= 200 and code ~= 201 and code ~= 204 then return false, "http_" .. tostring(code) end
        local body = res.Body or res.body
        if type(body) ~= "string" or body == "" then return false, "bad_response" end
        local dok, data = pcall(function() return HttpService:JSONDecode(body) end)
        if not dok or type(data) ~= "table" then return false, "bad_response" end
        if data.success == true then return true end
        return false, tostring(data.error or "unknown")
    end
    local FG = SuggestTab:AddLeftGroupbox(L["Suggestions / Help"], "message-square")
    FG:AddDropdown("FeedbackType", { Text = L["Type"], Values = { "Suggestion", "Bug", "Help" }, Default = "Suggestion" })
    FG:AddInput("FeedbackMsg", { Default = "", Numeric = false, Finished = false, ClearTextOnFocus = false, Text = L["Message"], Placeholder = L["500 chars max, no links"] })
    local fbStatus = FG:AddLabel("", true)
    local FEEDBACK_COOLDOWN, lastFeedback = 20, 0
    FG:AddButton({ Text = L["Send"], Func = function()
        local t = tick()
        if t - lastFeedback < FEEDBACK_COOLDOWN then
            setText(fbStatus, string.format(L["Wait %ds"], math.ceil(FEEDBACK_COOLDOWN - (t - lastFeedback))))
            return
        end
        local ftype = tostring(val("FeedbackType", "Suggestion")):lower()
        local msg = fbTrim(val("FeedbackMsg", ""))
        if msg == "" then setText(fbStatus, L["The message is empty."]); return end
        if #msg > 500 then setText(fbStatus, L["Too long (500 max)."]); return end
        local low = msg:lower()
        if low:find("http", 1, true) or low:find("discord.gg", 1, true) or low:find("www.", 1, true) or low:find(".gg/", 1, true) then
            setText(fbStatus, L["Links are not allowed."]); return
        end
        setText(fbStatus, L["Sending..."])
        task.spawn(function()
            local sok, err = sendFeedback(ftype, msg)
            if sok then
                lastFeedback = tick()
                setText(fbStatus, L["Sent. Thank you!"])
                pcall(function() Opt.FeedbackMsg:SetValue("") end)
            else
                setText(fbStatus, FB_ERRMAP[err] or (L["Failed: "] .. tostring(err)))
            end
        end)
    end })
    FG:AddLabel(L["Max 3 messages per hour."], true)
    local HelpGroup = SuggestTab:AddRightGroupbox("Help", "life-buoy")
    HelpGroup:AddLabel(L["Story tab → Auto Story plays the game for you. Lobby tab → Create Run starts a match."], true)
    if DISCORD_INVITE ~= "" then
        HelpGroup:AddButton({ Text = L["Copy Discord Invite"], Func = function()
            pcall(function() setclipboard(DISCORD_INVITE) end)
            notify(L["Discord link copied"])
        end })
    end
end)
