if not IS_LOBBY then
    section(L["Teleports"], function()
        local Tab = Window:AddTab(L["Teleports"], "arrow-up")
        local function pivotOf(path, fallback)
            return function()
                local m = Workspace
                for part in path:gmatch("[^%.]+") do m = m and m:FindFirstChild(part) end
                if m and m ~= Workspace then
                    local ok, cf = pcall(function() return m:IsA("BasePart") and m.CFrame or m:GetPivot() end)
                    if ok then SEEN[path] = cf.Position + Vector3.new(3, 0, 0); return SEEN[path] end
                end
                return SEEN[path] or fallback
            end
        end
        local SPOTS = {
            { "Abu Abdullah House", pivotOf("Objectives.Mission_AbuAbdullah", Vector3.new(390.2, 426.4, -4.8)) },
            { "Abu Abdullah", pivotOf("SHAEB", Vector3.new(444.3, 425.2, -36.8)) },
            { "Garden Entrance", pivotOf("EnterGarden", Vector3.new(296.8, 426.3, -187.7)) },
            { "Saudi Street", pivotOf("SaudiStreet", Vector3.new(334.6, 425.9, -172.1)) },
            { "Bakala Shop", pivotOf("Objectives.Mission_Bakala", Vector3.new(-165.2, 426.9, -306.2)) },
            { "Shop Worker", pivotOf("3amel2", Vector3.new(-194.7, 425.7, -335.2)) },
            { "School Entrance", function() return SEEN["EnterSchoolPrompt"] or Vector3.new(163.6, 426, -521.2) end },
        }
        local names = {}
        for _, s in ipairs(SPOTS) do names[#names + 1] = s[1] end
        local PB = Tab:AddLeftGroupbox(game.PlaceId == PART1_ID and L["Places"] or L["Objective"], "arrow-up")
        if game.PlaceId == PART1_ID then
            PB:AddDropdown("tp_spot", { Values = names, Default = names[1], Text = L["Place"] })
            PB:AddButton({ Text = L["Teleport"], Func = function()
                local want = val("tp_spot")
                for _, s in ipairs(SPOTS) do
                    if s[1] == want then
                        task.spawn(function() local p = s[2](); if p then moveTo(p) end end)
                        return
                    end
                end
            end })
        end
        PB:AddButton({ Text = L["Current Objective"], Func = function()
            task.spawn(function()
                local dp = missionPos(curMission())
                if dp then moveTo(dp.Position) else notify(L["No objective found"]) end
            end)
        end })
        local function others()
            local out = {}
            for _, p in ipairs(Players:GetPlayers()) do if p ~= lp then out[#out + 1] = p.Name end end
            table.sort(out)
            return out
        end
        local QB = Tab:AddRightGroupbox("Players", "users")
        QB:AddDropdown("tp_player", { Values = others(), Text = L["Player"], AllowNull = true })
        QB:AddButton({ Text = L["Teleport To Player"], Func = function()
            local p = Players:FindFirstChild(tostring(val("tp_player", "")))
            local r = p and p.Character and p.Character:FindFirstChild("HumanoidRootPart")
            if r then task.spawn(moveTo, r.Position) else notify(L["Player not found"]) end
        end })
        QB:AddButton({ Text = L["Refresh"], Func = function() pcall(function() Opt.tp_player:SetValues(others()) end) end })
    end)
end
