local COVERS = { ParkInitialCover = true, IntroGui = true, BlackScreen = true, BlackScreenGui = true, __TeleportFadeLayer = true, TeleportFade = true, TeleportFadeGui = true, DesertArrivalGui = true, SchoolArrivalGui = true, IntroBlackScreen = true }
local coverSeen = {}
local loadedAt = os.clock()
local function coverTick()
    if not on("st_skipblack") then return end
    if game.PlaceId == PART1_ID and lp:GetAttribute("ParkIntroStarted") ~= true
        and lp:GetAttribute("ParkArrivalReady") == true and once("ready", 8) then
        fire("PlayerReady", lp:GetAttribute("ParkArrivalToken"))
    elseif game.PlaceId == STORY2.DESERT and lp:GetAttribute("DesertArrivalReady") == true and not S.obj
        and not S.introSent and os.clock() - loadedAt > 8 then
        S.introSent = true
        fire("IntroEvents.IntroReady")
    end
    local pg = lp:FindFirstChild("PlayerGui"); if not pg then return end
    for _, g in ipairs(pg:GetChildren()) do
        if COVERS[g.Name] and g:IsA("ScreenGui") then
            if g.Enabled then
                coverSeen[g] = coverSeen[g] or os.clock()
                if os.clock() - coverSeen[g] > 8 then g.Enabled = false; coverSeen[g] = nil end
            else
                coverSeen[g] = nil
            end
        end
    end
end
local function startWorkers()
    hookEvents()
    STORY2.hook()
    buildIndex()
    track(RunService.Stepped:Connect(function()
        if not RUNNING then return end
        local c = lp.Character; if not c then return end
        if on("pl_noclip") or on("pl_fly") or S.gliding then
            S.noclipped = true
            for _, p in ipairs(c:GetDescendants()) do if p:IsA("BasePart") and p.CanCollide then p.CanCollide = false end end
        elseif S.noclipped then
            S.noclipped = false
            for _, n in ipairs({ "Torso", "UpperTorso", "LowerTorso" }) do
                local p = c:FindFirstChild(n); if p and p:IsA("BasePart") then p.CanCollide = true end
            end
        end
    end))
    track(RunService.Heartbeat:Connect(function(dt)
        if not RUNNING then return end
        local root, h = hrp(), hum()
        if not (root and h) then return end
        if on("pl_fly") then
            local cam = Workspace.CurrentCamera
            local dir = Vector3.zero
            if not UserInputService:GetFocusedTextBox() and cam then
                local cf = cam.CFrame
                if UserInputService:IsKeyDown(Enum.KeyCode.W) then dir = dir + cf.LookVector end
                if UserInputService:IsKeyDown(Enum.KeyCode.S) then dir = dir - cf.LookVector end
                if UserInputService:IsKeyDown(Enum.KeyCode.D) then dir = dir + cf.RightVector end
                if UserInputService:IsKeyDown(Enum.KeyCode.A) then dir = dir - cf.RightVector end
                if UserInputService:IsKeyDown(Enum.KeyCode.Space) then dir = dir + Vector3.yAxis end
                if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then dir = dir - Vector3.yAxis end
            end
            local spd = tonumber(val("pl_flyspeed", 50)) or 50
            root.AssemblyLinearVelocity = dir.Magnitude > 0 and dir.Unit * spd or Vector3.zero
        elseif on("pl_speed") and h.MoveDirection.Magnitude > 0 then
            local extra = tonumber(val("pl_speedval", 10)) or 10
            root.CFrame = root.CFrame + h.MoveDirection * extra * dt
        end
    end))
    track(UserInputService.JumpRequest:Connect(function()
        if on("pl_jump") then local h = hum(); if h then h:ChangeState(Enum.HumanoidStateType.Jumping) end end
    end))
    track(lp.Idled:Connect(function()
        if on("pl_afk") then pcall(function() VirtualUser:CaptureController(); VirtualUser:ClickButton2(Vector2.new()) end) end
    end))
    task.spawn(function()
        while RUNNING do
            pcall(evadeTick)
            pcall(STORY2.guards)
                        task.wait(0.1)
        end
    end)
    task.spawn(function()
        while RUNNING do
            pcall(staminaTick)
            if not IS_LOBBY then
                pcall(batteryTick)
                pcall(heatTick)
                pcall(scareTick)
                pcall(recordSafe)
            end
            pcall(worldTick)
            pcall(promptTick)
            pcall(coverTick)
            setText(UI.evCount, L["Escapes "] .. S.evades)
            if not IS_LOBBY then
                local g = GUIDE.current()
                setText(UI.gdTitle, tostring(g.title))
                setText(UI.gdSteps, tostring(g.steps or "-"))
                setText(UI.gdHint, g.hint or L["Nothing to solve right now."])
                local tp, r = GUIDE.targetPos(g), hrp()
                setText(UI.gdDist, (tp and r) and (L["Target · "] .. math.floor((tp - r.Position).Magnitude) .. L["m away"]) or L["Target · -"])
                setText(UI.stStep, on("st_auto") and S.step or L["Idle"])
                local m = curMission()
                setText(UI.stObj, m and (L["Objective · "] .. m.Name:gsub("^Mission_", "")) or L["Objective · -"])
            else
                local l = S.lobby
                if l and l.inQueue then
                    setText(UI.lbState, L["In queue · Part "] .. tostring(l.part or "?") .. (l.isHost and L[" · Host"] or ""))
                else
                    setText(UI.lbState, L["Not in queue"])
                end
            end
            task.wait(0.5)
        end
    end)
    task.spawn(function()
        while RUNNING do
            pcall(espTick)
            task.wait(0.25)
        end
    end)
    if IS_LOBBY then
        task.spawn(function()
            while RUNNING do
                if on("lb_auto") and not S.lobbyBusy and not inQueue() and not (S.lobby and S.lobby.teleporting) then
                    pcall(createRun)
                end
                task.wait(4)
            end
        end)
    else
        task.spawn(function()
            local lastStep, lastChange = nil, os.clock()
            while RUNNING do
                if S.step ~= lastStep then lastStep, lastChange = S.step, os.clock() end
                if S.storyBusy and S.tickThread and os.clock() - lastChange > 90 then
                    pcall(task.cancel, S.tickThread)
                    S.tickThread, S.storyBusy, S.guardPause, S.gliding = nil, false, false, false
                    lastChange = os.clock()
                    if S.forceFP and STORY2.restoreFP then STORY2.restoreFP() end
                    for _, cn in ipairs(S.stepConns or {}) do pcall(function() cn:Disconnect() end) end
                    S.stepConns = nil
                    if LOCK.conn then pcall(function() LOCK.conn:Disconnect() end); LOCK.conn = nil end
                    LOCK.block = false
                    fire("YellowMonsterUVUpdate", false, Vector3.zero, "None")
                end
                if on("st_auto") and alive() and not S.storyBusy then
                    S.storyBusy = true
                    S.tickThread = task.spawn(function()
                        pcall(storyTick)
                        S.storyBusy = false
                        S.tickThread = nil
                    end)
                elseif not on("st_auto") then
                    S.step = L["Idle"]
                end
                if on("pk_auto") and alive() then pcall(pickupTick) end
                task.wait(0.6)
            end
        end)
    end
end
startWorkers()
pcall(function() SaveManager:LoadAutoloadConfig() end)
notify(IS_LOBBY and L["Lobby loaded"] or L["Loaded"])

end
